const MONTH_NAMES = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December',
] as const

export function monthName(month: number): string {
  return MONTH_NAMES[(month - 1 + 12) % 12]
}

/** This month's and next month's normals for a destination, or null if unresolved. */
export function normalsFor(slug: string, month: number): MonthlyNormal | null {
  const rows = CLIMATE_NORMALS[slug]
  if (!rows) return null
  return rows.find((r) => r.month === ((month - 1 + 12) % 12) + 1) ?? null
}
